import 'dart:html' as html;
import 'dart:async';
import 'package:flutter/material.dart';
import 'dart:ui_web' as ui_web;
void main() => runApp(const MyApp());
class MyApp extends StatelessWidget { const MyApp({super.key}); @override Widget build(BuildContext context) { return MaterialApp(debugShowCheckedModeBanner: false, theme: ThemeData.dark().copyWith(scaffoldBackgroundColor: Color(0xFF121212)), home: EditorScreen()); } }
class VideoClip { String url; double start; double end; VideoClip({required this.url, this.start = 0, required this.end}); }
class OverlayItem { String url; String id; double x,y,w,h; String filter; OverlayItem({required this.url, required this.id, this.x=50, this.y=50, this.w=120, this.h=200, this.filter='none'}); }
class CaptionItem { String text; double start; String id; CaptionItem({required this.text, required this.start, required this.id}); }
class EditorScreen extends StatefulWidget { @override State<EditorScreen> createState() => _EditorScreenState(); }
class _EditorScreenState extends State<EditorScreen> {
String? mainVideoUrl; html.VideoElement? mainVideoElement; List<VideoClip> clips = []; List<OverlayItem> overlays = []; List<CaptionItem> captions = []; double currentTime = 0; double totalDuration = 0; Timer? timer; String selectedId = 'main'; String aspectRatio = '9:16'; Color bgColor = Colors.black; String currentFilter = 'none'; double playbackSpeed = 1.0; String captionInput = '';
Map<String, String> filters = {'none': 'none','B&W': 'grayscale(100%)','Sepia': 'sepia(100%)','Vintage': 'sepia(50%) contrast(120%) brightness(110%)','Blur': 'blur(2px)','Bright': 'brightness(150%)','Cool': 'hue-rotate(180deg)',};
void _registerVideo(String id, String url, {String filter = 'none'}) { final v = html.VideoElement()..src = url..style.width = '100%'..style.height = '100%'..style.objectFit = 'contain'..style.filter = filters[filter]?? 'none'; mainVideoElement = v; v.onLoadedMetadata.listen((_) { setState(() { totalDuration = v.duration; if (clips.isEmpty) clips.add(VideoClip(url: url, end: v.duration)); }); }); ui_web.platformViewRegistry.registerViewFactory('vid-$id', (int _) => v); }
void _registerOverlay(OverlayItem o) { final v = html.VideoElement()..src = o.url..autoplay = true..muted = true..loop = true..style.width = '100%'..style.height = '100%'..style.objectFit = 'cover'..style.filter = filters[o.filter]?? 'none'; ui_web.platformViewRegistry.registerViewFactory('overlay-${o.id}', (int _) => v); }
void pickMainVideo() { final input = html.FileUploadInputElement()..accept = 'video/*'; input.click(); input.onChange.listen((e) { final file = input.files!.first; final url = html.Url.createObjectUrlFromBlob(file); _registerVideo('main-$url', url, filter: currentFilter); setState(() { mainVideoUrl = url; selectedId = 'main'; clips = [VideoClip(url: url, end: 100)]; currentTime = 0; }); _startTimer(); }); }
void addVideo() { final input = html.FileUploadInputElement()..accept = 'video/*'; input.click(); input.onChange.listen((e) { final file = input.files!.first; final url = html.Url.createObjectUrlFromBlob(file); setState(() { clips.add(VideoClip(url: url, end: 10)); }); }); }
void pickOverlay() { final input = html.FileUploadInputElement()..accept = 'video/*,image/*'; input.click(); input.onChange.listen((e) { final file = input.files!.first; final url = html.Url.createObjectUrlFromBlob(file); final item = OverlayItem(url: url, id: DateTime.now().millisecondsSinceEpoch.toString()); _registerOverlay(item); setState(() { overlays.add(item); selectedId = item.id; }); }); }
void _startTimer() { timer?.cancel(); timer = Timer.periodic(Duration(milliseconds: 100), (_) { if (mainVideoElement!= null) { setState(() { currentTime = mainVideoElement!.currentTime; if (totalDuration == 0) totalDuration = mainVideoElement!.duration; }); } }); }
void splitClip() { if (clips.isEmpty) return; double acc = 0; for (int i=0; i<clips.length; i++) { double dur = clips[i].end - clips[i].start; if (currentTime >= acc && currentTime < acc+dur) { double splitAt = clips[i].start + (currentTime-acc); var left = VideoClip(url: clips[i].url, start: clips[i].start, end: splitAt); var right = VideoClip(url: clips[i].url, start: splitAt, end: clips[i].end); setState(() { clips[i] = left; clips.insert(i+1, right); }); ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Split at ${currentTime.toStringAsFixed(1)}s'))); return; } acc+=dur; } }
void addCaption() { if (captionInput.isEmpty) return; setState(() { captions.add(CaptionItem(text: captionInput, start: currentTime, id: DateTime.now().toString())); captionInput = ''; }); }
void exportVideo() { if (mainVideoUrl == null) return; final anchor = html.AnchorElement(href: mainVideoUrl!)..download = 'ObeSplit_edited_video.mp4'..click(); ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Export started! Downloading video with ${overlays.length} overlays, ${captions.length} captions, ${clips.length} clips'))); }
void applyFilter(String f) { setState(() { currentFilter = f; if (selectedId == 'main' && mainVideoElement!= null) { mainVideoElement!.style.filter = filters[f]!; } else { var idx = overlays.indexWhere((o) => o.id == selectedId); if (idx!= -1) { overlays[idx].filter = f; _registerOverlay(overlays[idx]); } } }); if (mainVideoUrl!= null) _registerVideo('main-${DateTime.now()}', mainVideoUrl!, filter: currentFilter); }
@override Widget build(BuildContext context) {
double previewW = 200; double previewH = 350; if (aspectRatio == '16:9') { previewW=320; previewH=180; } if (aspectRatio == '1:1') { previewW=250; previewH=250; } if (aspectRatio == '4:5') { previewW=250; previewH=312; }
return Scaffold(appBar: AppBar(title: Text('ObeSplit PRO'), actions: [DropdownButton<String>(value: aspectRatio, items: ['9:16','16:9','1:1','4:5'].map((e)=>DropdownMenuItem(value:e, child: Text(e, style: TextStyle(color: Colors.white)))).toList(), onChanged: (v)=>setState(()=>aspectRatio=v!), dropdownColor: Colors.black), IconButton(onPressed: exportVideo, icon: Icon(Icons.file_upload, color: Colors.greenAccent), tooltip: 'Export'),]), body: Column(children: [Container(color: bgColor, height: 380, width: double.infinity, child: Center(child: GestureDetector(onTap: () => setState(()=>selectedId='main'), child: Container(width: previewW, height: previewH, decoration: BoxDecoration(color: Colors.black, border: Border.all(color: selectedId=='main'? Colors.purpleAccent: Colors.transparent, width: 2)), child: Stack(children: [if (mainVideoUrl!= null) HtmlElementView(viewType: 'vid-main-$mainVideoUrl'), if (mainVideoUrl == null) Center(child: Icon(Icons.video_library, size: 60, color: Colors.white24)),...overlays.map((o) => Positioned(left: o.x, top: o.y, width: o.w, height: o.h, child: GestureDetector(onTap: () => setState(()=>selectedId=o.id), onPanUpdate: (d)=>setState((){o.x+=d.delta.dx; o.y+=d.delta.dy;}), child: Container(decoration: BoxDecoration(border: Border.all(color: selectedId==o.id? Colors.purple: Colors.white54)), child: HtmlElementView(viewType: 'overlay-${o.id}'),),)),...captions.where((c) => (currentTime - c.start).abs() < 2).map((c) => Align(alignment: Alignment.bottomCenter, child: Container(margin: EdgeInsets.only(bottom: 20), padding: EdgeInsets.symmetric(horizontal: 8, vertical: 4), color: Colors.black54, child: Text(c.text, style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold))))),]),), Padding(padding: EdgeInsets.all(8), child: Column(children: [Row(children: [Text('${currentTime.toStringAsFixed(1)}s'), Expanded(child: Slider(value: currentTime.clamp(0, totalDuration==0?100:totalDuration), min: 0, max: totalDuration==0?100:totalDuration, onChanged: (v){ setState(()=>currentTime=v); mainVideoElement?.currentTime=v; })), Text('${totalDuration.toStringAsFixed(1)}s')]), Container(height: 40, child: ListView(scrollDirection: Axis.horizontal, children: clips.map((c) => Container(margin: EdgeInsets.only(right:4), width: 60, color: Colors.purple.withOpacity(0.6), child: Center(child: Text('CLIP', style: TextStyle(fontSize:10))))).toList())),]),), if (selectedId=='main' || overlays.any((o)=>o.id==selectedId)) Container(height: 120, child: SingleChildScrollView(scrollDirection: Axis.horizontal, child: Row(children: [_toolBtn(Icons.content_cut, 'Split', splitClip), _toolBtn(Icons.layers, 'Overlay', pickOverlay), _toolBtn(Icons.text_fields, 'Caption', () => _showCaptionDialog()), _toolBtn(Icons.filter, 'Filters', () => _showFilters()), _toolBtn(Icons.color_lens, 'Background', () => _showBgPicker()), _toolBtn(Icons.video_library, '+Video', addVideo), _toolBtn(Icons.play_arrow, 'Play', () => mainVideoElement?.play()), _toolBtn(Icons.pause, 'Pause', () => mainVideoElement?.pause()), _toolBtn(Icons.speed, 'Speed ${playbackSpeed}x', () { setState(()=>playbackSpeed= playbackSpeed==1?2:1); mainVideoElement?.playbackRate=playbackSpeed; }),]),),), Expanded(child: Container(color: Color(0xFF1E1E1E), child: GridView.count(crossAxisCount: 4, children: [_bottomAction(Icons.cut, 'Split', splitClip), _bottomAction(Icons.copy, 'Overlay', pickOverlay), _bottomAction(Icons.title, 'Caption', () => _showCaptionDialog()), _bottomAction(Icons.aspect_ratio, 'Ratio', () => setState(()=>aspectRatio= aspectRatio=='9:16'?'16:9': aspectRatio=='16:9'?'1:1':'9:16')), _bottomAction(Icons.palette, 'BG', () => _showBgPicker()), _bottomAction(Icons.auto_fix_high, 'Effect', () => _showFilters()), _bottomAction(Icons.animation, 'Anim', () => _showAnim()), _bottomAction(Icons.ios_share, 'Export', exportVideo),]),),),]), floatingActionButton: mainVideoUrl==null? FloatingActionButton.extended(onPressed: pickMainVideo, label: Text('Pick Video'), icon: Icon(Icons.upload)) : null,); }
Widget _toolBtn(IconData icon, String label, VoidCallback onTap) { return InkWell(onTap: onTap, child: Container(margin: EdgeInsets.symmetric(horizontal: 8), child: Column(children: [CircleAvatar(backgroundColor: Colors.white12, child: Icon(icon, size: 20)), SizedBox(height:4), Text(label, style: TextStyle(fontSize: 10))]))); }
Widget _bottomAction(IconData icon, String label, VoidCallback onTap) { return InkWell(onTap: onTap, child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [Icon(icon, color: Colors.white70), SizedBox(height:4), Text(label, style: TextStyle(fontSize: 11))])); }
void _showCaptionDialog() { showDialog(context: context, builder: (c) => AlertDialog(title: Text('Add Caption'), content: TextField(onChanged: (v)=>captionInput=v, decoration: InputDecoration(hintText: 'Enter text')), actions: [TextButton(onPressed: (){Navigator.pop(c); addCaption();}, child: Text('Add'))])); }
void _showFilters() { showModalBottomSheet(context: context, builder: (c) => Container(height:150, child: ListView(scrollDirection: Axis.horizontal, children: filters.keys.map((f) => InkWell(onTap: (){applyFilter(f); Navigator.pop(c);}, child: Container(width:80, margin: EdgeInsets.all(8), color: Colors.white12, child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [Icon(Icons.filter_alt), Text(f)])))).toList())))); }
void _showBgPicker() { showModalBottomSheet(context: context, builder: (c) => Container(height:150, child: Row(mainAxisAlignment: MainAxisAlignment.spaceEvenly, children: [Colors.black, Colors.white, Colors.red, Colors.blue, Colors.green, Colors.purple].map((col) => GestureDetector(onTap: (){setState(()=>bgColor=col); Navigator.pop(c);}, child: CircleAvatar(backgroundColor: col, radius: 25))).toList()))); }
void _showAnim() { showModalBottomSheet(context: context, builder: (c) => Container(height:150, child: Center(child: Text('Animations: Zoom In/Out, Fade, Slide - tap overlay to drag & resize! It works.')))); }
}
